import sys, base64, zlib
if hasattr(sys.stdout, 'reconfigure'): sys.stdout.reconfigure(encoding='utf-8', errors='replace', line_buffering=True)
if hasattr(sys.stderr, 'reconfigure'): sys.stderr.reconfigure(encoding='utf-8', errors='replace', line_buffering=True)
_k = 0x5a
_p = ''
exec(zlib.decompress(bytes([_b ^ _k for _b in base64.b64decode(_p)])).decode('utf-8'), {'__name__': '__main__', '__file__': '<wewill_loader>'})
